import{_ as a,o as e,c as s,a2 as i}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"验收与证据","description":"Hearth 如何判断一项能力真的完成，以及需要保留哪些证据。","frontmatter":{"title":"验收与证据","description":"Hearth 如何判断一项能力真的完成，以及需要保留哪些证据。","outline":[2,3]},"headers":[],"relativePath":"delivery/acceptance.md","filePath":"delivery/acceptance.md","lastUpdated":null}'),n={name:"delivery/acceptance.md"};function l(d,t,r,h,p,o){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="验收与证据" tabindex="-1">验收与证据 <a class="header-anchor" href="#验收与证据" aria-label="Permalink to &quot;验收与证据&quot;">​</a></h1><p class="lead">Hearth 不用“页面存在”“代码合并”或“测试通过”冒充交付。验收必须回答三个问题：做了什么、证据在哪里、还有什么没有证明。</p><h2 id="完成-的定义" tabindex="-1">“完成”的定义 <a class="header-anchor" href="#完成-的定义" aria-label="Permalink to &quot;“完成”的定义&quot;">​</a></h2><p>一项能力只有同时满足以下条件，才能标记为完成：</p><ol><li><strong>有用户可见结果。</strong> 用户能在界面、产物或回执中看到结果，而不是只看到模型说“好了”。</li><li><strong>有可复核证据。</strong> 输入、运行记录、产物摘要、审批和外部回执可以追溯。</li><li><strong>有失败路径。</strong> 失败会进入可恢复或明确失败状态，不伪造成功，不盲目重试外部动作。</li><li><strong>有真实验收。</strong> 至少用真实任务、真实设备或真实账户跑过约定场景；自动测试不能替代真实验收。</li></ol><h2 id="测试层级" tabindex="-1">测试层级 <a class="header-anchor" href="#测试层级" aria-label="Permalink to &quot;测试层级&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>证明什么</th><th>不能证明什么</th></tr></thead><tbody><tr><td>单元测试</td><td>状态机、预算、权限、提取、加密等纯逻辑</td><td>真实环境、真实账户、用户是否愿意使用</td></tr><tr><td>API / 集成测试</td><td>服务端路由、投影、审批、备份、同步等代码闭环</td><td>真实桌面、真实网络、长期运行</td></tr><tr><td>隔离实例运行</td><td>端到端链路在受控环境中可执行</td><td>真实用户任务和失败恢复意愿</td></tr><tr><td>真实任务验收</td><td>约定任务在真实环境中完成并可核对</td><td>长期稳定性和所有边界</td></tr><tr><td>长期运行验收</td><td>数周运行、资源漂移、升级回退</td><td>未覆盖的任务类型</td></tr></tbody></table><p>当前自动测试基线是 <strong>40 个测试文件、199 个测试</strong>。它覆盖了服务层、API、模型协议、原生工具循环、预算、权限、检查点、提案确认、桌面边界、记忆、方法、同步、安全、备份与运维，但不替代真实验收。</p><h2 id="复现当前验证" tabindex="-1">复现当前验证 <a class="header-anchor" href="#复现当前验证" aria-label="Permalink to &quot;复现当前验证&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p>2026-11-06 的运行结果：</p><table tabindex="0"><thead><tr><th>检查</th><th>结果</th></tr></thead><tbody><tr><td><code>npm test</code></td><td>40 个测试文件、199 个测试通过</td></tr><tr><td><code>npm run typecheck</code></td><td>通过</td></tr><tr><td><code>npm run build</code></td><td>通过</td></tr><tr><td><code>npm run docs:build</code></td><td>通过</td></tr></tbody></table><h2 id="证据规则" tabindex="-1">证据规则 <a class="header-anchor" href="#证据规则" aria-label="Permalink to &quot;证据规则&quot;">​</a></h2><h3 id="保留失败证据" tabindex="-1">保留失败证据 <a class="header-anchor" href="#保留失败证据" aria-label="Permalink to &quot;保留失败证据&quot;">​</a></h3><ul><li>网页访问失败时保留 HTTP 状态、最终 URL、抓取时间和失败原因。</li><li>任务缺少产物时进入恢复或失败，不把空文件当结果。</li><li>外部动作结果不确定时先对账，不盲目重试。</li><li>设备撤销后无法操作要有演练记录，而不是只写“已实现”。</li></ul><h3 id="外部动作必须可核对" tabindex="-1">外部动作必须可核对 <a class="header-anchor" href="#外部动作必须可核对" aria-label="Permalink to &quot;外部动作必须可核对&quot;">​</a></h3><ul><li>外部动作先生成预览。</li><li>审批绑定参数指纹，只执行一次。</li><li>效果账本记录执行结果和回执。</li><li>审批被拒绝或失效时，草稿与任务状态同步更新。</li></ul><h3 id="不伪造成功" tabindex="-1">不伪造成功 <a class="header-anchor" href="#不伪造成功" aria-label="Permalink to &quot;不伪造成功&quot;">​</a></h3><ul><li>T04 的 WCAG 页面访问失败被保留为证据。</li><li>T07 因未提交测试文件而未通过，没有推送分支或创建 PR。</li><li>T08 的评论审批仍是 <code>pending</code>，没有外部副作用。</li><li>备份不包含产物正文时，界面和文档都明确说明边界。</li></ul><h2 id="验收记录模板" tabindex="-1">验收记录模板 <a class="header-anchor" href="#验收记录模板" aria-label="Permalink to &quot;验收记录模板&quot;">​</a></h2><p>每个阶段或工作流完成时，至少保留以下记录：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工作流：</span></span>
<span class="line"><span>验收日期：</span></span>
<span class="line"><span>真实环境：</span></span>
<span class="line"><span>任务数量：</span></span>
<span class="line"><span>通过 / 失败 / 待批准：</span></span>
<span class="line"><span>每个任务的输入与输出路径：</span></span>
<span class="line"><span>失败原因与恢复方式：</span></span>
<span class="line"><span>外部动作与回执：</span></span>
<span class="line"><span>仍未证明的边界：</span></span></code></pre></div><h2 id="阶段一证据索引" tabindex="-1">阶段一证据索引 <a class="header-anchor" href="#阶段一证据索引" aria-label="Permalink to &quot;阶段一证据索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>证据</th><th>位置</th></tr></thead><tbody><tr><td>第一阶段验收报告</td><td><code>eval/phase-1-acceptance.md</code></td></tr><tr><td>15 项任务运行与产物</td><td><code>eval/runs/T01</code> … <code>eval/runs/T15</code></td></tr><tr><td>运行清单与 SHA-256</td><td>各任务目录下的 <code>run-manifest.json</code></td></tr><tr><td>自动测试</td><td><code>npm test</code></td></tr><tr><td>类型检查与构建</td><td><code>npm run typecheck</code>、<code>npm run build</code></td></tr></tbody></table><p>逐项结果见<a href="/hearth-os/delivery/mvp.html">第一阶段 MVP 验收</a>。</p><h2 id="下一步验收重点" tabindex="-1">下一步验收重点 <a class="header-anchor" href="#下一步验收重点" aria-label="Permalink to &quot;下一步验收重点&quot;">​</a></h2><p>下一轮验收不再增加“看起来完整”的页面，而是补齐：</p><ol><li>真实邮件/日历账户与 10–15 个日常内容任务。</li><li>至少 5 个真实桌面任务及高风险失败演练。</li><li>手机审批/接管与 5–10 个主动任务打扰验收。</li><li>错误记忆/错误方法与采用前后生产对照。</li><li>双设备、断网、设备丢失和备份恢复演练。</li><li>数周连续运行、资源漂移和版本升级回退。</li></ol><p>这些项目没有完成前，阶段二至六保持“部分完成”。</p>`,29)])])}const k=a(n,[["render",l]]);export{u as __pageData,k as default};
